const server = http.createServer((req, res) => {
  res.writeHead(201);
  res.end(req.method);
});
server.listen(0, async () => {
  const url = `http://localhost:${server.address().port}`;
  const res = await fetch(url, { method: 'POST' });
  console.log(res.status, await res.text());
  server.close();
});
